        0xE7 => 'c', 0xE8 => 'e', 0xE9 => 'e', 0xEA => 'e', 0xEB => 'e',
        0xEC => 'i', 0xED => 'i', 0xEE => 'i', 0xEF => 'i', 0xF1 => 'n',
        0xF2 => 'o', 0xF3 => 'o', 0xF4 => 'o', 0xF5 => 'o', 0xF6 => 'o',
