        0xBF => '?', 0xA1 => '!', 0xAB => '"', 0xBB => '"', 0xAA => 'a', 0xBA => 'o',
        0xB0 => 'o', 0xA9 => 'O', 0xAE => 'O', 0xB7 => '.', 0xA0 => ' ',
        0x91 => "'", 0x92 => "'", 0x93 => '"', 0x94 => '"', 0x96 => '-', 0x97 => '-',
        0x85 => '.', 0x80 => 'E', 0xA4 => '$', 0xA3 => '$', 0xB1 => '+', 0xD7 => 'x',
    ];

    private static array $cache = [];

    public static function anchos(string $fuente): array
    {
        $clave = self::normalizar($fuente);
        if (isset(self::$cache[$clave])) {
            return self::$cache[$clave];
        }
        $ascii = self::ASCII[$clave] ?? self::ASCII['helvetica'];
        $tabla = array_fill(0, 256, 500);
        foreach ($ascii as $i => $an) {
            $tabla[32 + $i] = $an;
        }
        foreach (self::BASE_ACENTOS as $code => $base) {
            $tabla[$code] = $tabla[ord($base)] ?? 500;
        }
        // Caracteres altos poco comunes: ancho del espacio en blanco por defecto.
        self::$cache[$clave] = $tabla;
        return $tabla;
    }

    public static function nombrePdf(string $fuente): string
    {
        return match (self::normalizar($fuente)) {
            'helveticab'  => 'Helvetica-Bold',
            'helveticai'  => 'Helvetica-Oblique',
            'helveticabi' => 'Helvetica-BoldOblique',
            'times'       => 'Times-Roman',
            'timesb'      => 'Times-Bold',
            'timesi'      => 'Times-Italic',
            'timesbi'     => 'Times-BoldItalic',
            'courier'     => 'Courier',
            'courierb'    => 'Courier-Bold',
            default       => 'Helvetica',
        };
    }

    private static function normalizar(string $f): string
    {
        $f = strtolower(str_replace(['-', ' '], '', $f));
        $f = str_replace('ib', 'bi', $f);
        if (str_starts_with($f, 'courier')) {
            return str_contains($f, 'b') && $f !== 'courier' ? 'courierb' : 'courier';
        }
        if (str_starts_with($f, 'times')) {
            $suf = substr($f, 5);
            return 'times' . (in_array($suf, ['b', 'i', 'bi'], true) ? $suf : '');
        }
        $suf = str_starts_with($f, 'helvetica') ? substr($f, 9) : '';
        return 'helvetica' . (in_array($suf, ['b', 'i', 'bi'], true) ? $suf : '');
    }
}
